/**
 * The Nigerian Bar Association seal, inlined for print.
 *
 * expo-print renders the certificate from an HTML string and cannot resolve a
 * bundled asset path from inside it, so the artwork has to travel with the
 * markup as a data URI. Both are resized from assets/images/nba-logo.png:
 * carrying the 884px original would triple the payload for no visible gain at
 * the sizes these print.
 *
 * SEAL_WATERMARK is pre-faded in the image itself rather than by CSS opacity,
 * which some print renderers drop on images.
 *
 * Regenerate with scratchpad/imgtool/make-seal.mjs if the artwork changes.
 * This is the generic Association seal; the branch's own seal, with the branch
 * named in the ring, should replace it when supplied.
 */

export const SEAL = 'data:image/png;base64,';

export const SEAL_WATERMARK = 'data:image/png;base64,';
